{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Dexetimide, a structurally related N-benzylpiperidine, is reported to have good brain penetration and is considered suitable for PET neuroreceptor imaging, directly supporting CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In mice, a closely related N-benzylpiperidine spiro compound showed a brain-to-blood ratio of 2.2 that increased to 6.3, confirming ready passage across the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In female CD-1 mice, the same compound class achieved rapid and significant brain uptake of 2.20% injected dose per gram within 5 minutes, demonstrating meaningful CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A related N-benzylpiperidine radiotracer showed 3.4% injected dose per gram brain uptake and labeled sigma receptors in brain regions, confirming effective blood-brain barrier passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Even a much larger N-benzylpiperidine-containing compound was detected in mouse brain at 10-20% of blood concentration, indicating that this structural family can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In monkeys, an N-benzylpiperidine iodobenzamide showed significant accumulation of radioactivity in the brain, providing direct primate evidence for CNS penetration in this chemical series.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query contains an N-benzylpiperidine moiety and dimethoxyaryl system shared with multiple compounds that demonstrate robust brain penetration in vivo; all high-transfer evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule, but multiple close analogues with the same N-benzylpiperidine pharmacophore show clear brain uptake.",
    "Efflux liability was not explicitly assessed, but the consistent positive in vivo data across species and structural variants outweigh this uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

